	outPoints := gkrcore.CollectOutgoingEvalPoints(level, levelI, r.outgoingEvalPoints)

	uniqueInputs := r.circuit.UniqueGateInputs(level)
	evals := make([]fr.Element, len(uniqueInputs)*len(outPoints))
