// Verify the consistency of the claimed output with the claimed input, and return the evaluation
// claims on the circuit's inputs and outputs. A nil error means nothing until the returned Claims
// are checked: Verify reads no assignment, so the caller must call Claims.Check itself, on every
// claim, including those on exported inputs under gkrapi.ConsolidateNone, which no level
// cross-checks. The claim values returned to the caller, the output evaluations among them, are
// not bound into the transcript.
//
// The transcript starts empty, so for soundness the verifier must seed hasher, as the prover did,
// by writing to it a commitment to the circuit, the schedule, the number of instances and the input
// and output columns, computed from values it trusts.
func Verify(c Circuit, schedule constraint.GkrProvingSchedule, logNbInstances int, proof Proof, hasher hash.FieldHasher[fr.Element, fr.Element]) (Claims, error) {
	if logNbInstances < 1 {
		return nil, errors.New("number of variables must be positive")
	}
	r := newResources(c, schedule, logNbInstances, hasher)

	if len(proof) != len(schedule)+1 {
		return nil, fmt.Errorf("proof has %d levels, expected %d", len(proof), len(schedule)+1)
	}
	outputLevel := proof[len(schedule)]
	if len(outputLevel.partialSumPolys) != 0 {
		return nil, errors.New("output level has partial sum polynomials")
	}
	if len(outputLevel.finalEvalProof) != len(c.Outputs()) {
		return nil, fmt.Errorf("output level has %d evaluations, expected %d", len(outputLevel.finalEvalProof), len(c.Outputs()))
	}

	view := c.LevelCircuit(schedule, 0, identityGate())
	for levelI, level := range schedule {
		levelCircuit := c
		if levelI == 0 {
			levelCircuit = view
		}
		nbUniqueInputs := len(levelCircuit.UniqueGateInputs(level))
		wantFinalEvalLen := nbUniqueInputs * level.NbOutgoingEvalPoints()
		if len(proof[levelI].finalEvalProof) != wantFinalEvalLen {
			return nil, fmt.Errorf("level %d: got %d final evaluations, expected %d", levelI, len(proof[levelI].finalEvalProof), wantFinalEvalLen)
		}
		if _, isSkip := level.(*constraint.GkrSkipLevel); isSkip {
			if len(proof[levelI].partialSumPolys) != 0 {
				return nil, fmt.Errorf("level %d: skip level has partial sum polynomials", levelI)
			}
		} else if len(proof[levelI].partialSumPolys) != logNbInstances {
			return nil, fmt.Errorf("level %d: got %d partial sum polynomials, expected %d", levelI, len(proof[levelI].partialSumPolys), logNbInstances)
		}
	}

	// Derive the initial challenge point
	firstChallenge := make([]fr.Element, r.nbVars)
	for j := range r.nbVars {
		firstChallenge[j] = r.transcript.Squeeze()
	}
	r.outgoingEvalPoints[len(schedule)] = [][]fr.Element{firstChallenge}
	var absorbedOutputEvals []fr.Element
	for i, w := range c.Outputs() {
		if r.consolidated[w] {
			absorbedOutputEvals = append(absorbedOutputEvals, outputLevel.finalEvalProof[i])
		}
	}
	r.transcript.Absorb(absorbedOutputEvals...)
	gkrcore.AppendOutputClaims(r.claims, c, firstChallenge, outputLevel.finalEvalProof, func(wI int) bool { return !r.consolidated[wI] })

	for levelI := len(schedule) - 1; levelI >= 1; levelI-- {
		if err := r.verifyLevel(levelI, proof); err != nil {
			return nil, err
		}
	}
	r.circuit = view
	if err := r.verifyLevel(0, proof); err != nil {
		return nil, err
	}
	return r.claims, nil
}

// Complete the circuit evaluation from input values
func (a WireAssignment) Complete(circuit Circuit) WireAssignment {

	nbInstances := a.NumInstances()
	evaluators := make([]evaluator.GateEvaluator, len(circuit))

	for i := range circuit {
		if len(a[i]) != nbInstances {
			a[i] = make([]fr.Element, nbInstances)
		}
		if !circuit[i].IsInput() {
			evaluators[i] = evaluator.NewGateEvaluator(circuit[i].Gate.Evaluate, len(circuit[i].Inputs))
		}
	}

	for i := range nbInstances {
		for wI := range circuit {
			if !circuit[wI].IsInput() {
				for _, in := range circuit[wI].Inputs {
					evaluators[wI].PushInput(a[in][i])
				}
				a[wI][i].Set(evaluators[wI].Evaluate())
			}
		}
	}

	return a
}

// NumInstances returns the number of instances a assigns values to. It panics if a is empty.
func (a WireAssignment) NumInstances() int {
	for _, aW := range a {
		if aW != nil {
			return len(aW)
		}
	}
	panic("empty assignment")
}

// NumVars returns log₂ of the number of instances a assigns values to. It panics if a is empty.
func (a WireAssignment) NumVars() int {
	for _, aW := range a {
		if aW != nil {
			return aW.NumVars()
		}
	}
	panic("empty assignment")
}

func iterateElems(elems []fr.Element, counter *int, yield func(int, *fr.Element) bool) bool {
	for i := range elems {
		if !yield(*counter, &elems[i]) {
			return false
		}
		*counter++
	}
	return true
}

// Flatten yields the proof's elements by position. For each entry of the proof, in order, it
// yields the coefficients of its partial sum polynomials, then its final evaluations.
// DeserializeProof reads the same order.
func (p Proof) Flatten() iter.Seq2[int, *fr.Element] {
	return func(yield func(int, *fr.Element) bool) {
		var counter int
		for i := range p {
			for _, poly := range p[i].partialSumPolys {
				if !iterateElems(poly, &counter, yield) {
					return
				}
			}
			if !iterateElems(p[i].finalEvalProof, &counter, yield) {
				return
			}
		}
	}
}

// DeserializeProof is the inverse of Proof.Flatten: it rebuilds the proof for c and schedule from
// its elements. The result aliases serialized. It returns an error if the length of serialized
// does not match c and schedule.
func DeserializeProof(c Circuit, schedule constraint.GkrProvingSchedule, serialized []fr.Element) (Proof, error) {
	identity := identityGate()
	logNbInstances, err := gkrcore.ComputeLogNbInstances(c, schedule, len(serialized), identity)
	if err != nil && !errors.Is(err, gkrcore.ErrNbInstancesUndetermined) {
		return nil, err
	}

	next := func(n int) []fr.Element {
		res := serialized[:n]
		serialized = serialized[n:]
		return res
	}

	proof := make(Proof, len(schedule)+1)
	for levelI, level := range schedule {
		levelCircuit := c.LevelCircuit(schedule, levelI, identity)
		nbUniqueInputs := len(levelCircuit.UniqueGateInputs(level))
		if _, isSkip := level.(*constraint.GkrSkipLevel); isSkip {
			proof[levelI].finalEvalProof = next(nbUniqueInputs * level.NbOutgoingEvalPoints())
		} else {
			degree := levelCircuit.ZeroCheckDegree(level)
			proof[levelI].partialSumPolys = make([]polynomial.Polynomial, logNbInstances)
			for j := range proof[levelI].partialSumPolys {
				proof[levelI].partialSumPolys[j] = next(degree)
			}
			proof[levelI].finalEvalProof = next(nbUniqueInputs)
		}
	}
	proof[len(schedule)].finalEvalProof = next(len(c.Outputs()))
	return proof, nil
}
